file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/datatypes/TaskEvent.java", "file_text": "package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    public static final int EVENT_SUBMIT = 0;

    private long timestampMicros;
    private long jobId;
    private long taskIndex;
    private int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, long taskIndex, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public long getTaskIndex() {
        return taskIndex;
    }

    public int getEventType() {
        return eventType;
    }

    public static TaskEvent fromCsvLine(String line) {
        // time,missing_info,job_id,task_index,machine_id,event_type,...
        String[] parts = line.split(",", -1);
        if (parts.length < 6) {
            return null;
        }

        long ts = parseLong(parts[0], -1L);
        long jobId = parseLong(parts[2], -1L);
        long taskIndex = parseLong(parts[3], -1L);
        int eventType = (int) parseLong(parts[5], -1L);

        if (ts < 0 || jobId < 0 || eventType < 0) {
            return null;
        }
        return new TaskEvent(ts, jobId, taskIndex, eventType);
    }

    private static long parseLong(String s, long defaultVal) {
        if (s == null || s.isEmpty()) {
            return defaultVal;
        }
        try {
            return Long.parseLong(s);
        } catch (NumberFormatException e) {
            return defaultVal;
        }
    }
}
