file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/datatypes/JobEvent.java", "file_text": "package clusterdata.datatypes;

import java.io.Serializable;

public class JobEvent implements Serializable {
    // Known terminal event types for Google cluster trace job events.
    public static final int EVENT_FAIL = 3;
    public static final int EVENT_FINISH = 4;
    public static final int EVENT_KILL = 5;
    public static final int EVENT_LOST = 6;

    private long timestampMicros;
    private long jobId;
    private int eventType;

    public JobEvent() {}

    public JobEvent(long timestampMicros, long jobId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public boolean isTerminal() {
        return eventType == EVENT_FAIL
                || eventType == EVENT_FINISH
                || eventType == EVENT_KILL
                || eventType == EVENT_LOST;
    }

    public static JobEvent fromCsvLine(String line) {
        // time,missing_info,job_id,event_type,...
        String[] parts = line.split(",", -1);
        if (parts.length < 4) {
            return null;
        }

        long ts = parseLong(parts[0], -1L);
        long jobId = parseLong(parts[2], -1L);
        int eventType = (int) parseLong(parts[3], -1L);

        if (ts < 0 || jobId < 0 || eventType < 0) {
            return null;
        }
        return new JobEvent(ts, jobId, eventType);
    }

    private static long parseLong(String s, long defaultVal) {
        if (s == null || s.isEmpty()) {
            return defaultVal;
        }
        try {
            return Long.parseLong(s);
        } catch (NumberFormatException e) {
            return defaultVal;
        }
    }
}
