", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.ReduceFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.SingleOutputStreamOperator;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.RichSourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final class TaskEventSource extends RichSourceFunction<TaskEvent> {
        private final String inputPath;
        private volatile boolean running = true;

        private TaskEventSource(String inputPath) {
            this.inputPath = inputPath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (inputPath == null) {
                return;
            }

            Path p = Paths.get(inputPath);
            InputStream in = Files.newInputStream(p);
            if (inputPath.endsWith(".gz")) {
                in = new GZIPInputStream(in);
            }

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    TaskEvent ev = TaskEvent.fromCsvLine(line);
                    if (ev == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(ev);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class JobEventSource extends RichSourceFunction<JobEvent> {
        private final String inputPath;
        private volatile boolean running = true;

        private JobEventSource(String inputPath) {
            this.inputPath = inputPath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (inputPath == null) {
                return;
            }

            Path p = Paths.get(inputPath);
            InputStream in = Files.newInputStream(p);
            if (inputPath.endsWith(".gz")) {
                in = new GZIPInputStream(in);
            }

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    JobEvent ev = JobEvent.fromCsvLine(line);
                    if (ev == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(ev);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    private static final class StageCountWindow extends ProcessWindowFunction<Long, Tuple2<Long, Long>, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Long> elements, Collector<Tuple2<Long, Long>> out) {
            Long count = elements.iterator().next();
            out.collect(Tuple2.of(key, count));
        }
    }

    private static final class MaxReduce implements ReduceFunction<Tuple2<Long, Long>> {
        @Override
        public Tuple2<Long, Long> reduce(Tuple2<Long, Long> a, Tuple2<Long, Long> b) {
            return Tuple2.of(a.f0, Math.max(a.f1, b.f1));
        }
    }

    private static final class EmitAfterFinished extends KeyedProcessFunction<Long, Tuple2<Long, Long>, String> {
        private final long maxEventTime;

        private transient ValueState<Long> maxStageCount;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Boolean> timerRegistered;

        private EmitAfterFinished(long maxEventTime) {
            this.maxEventTime = maxEventTime;
        }

        @Override
        public void open(Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            timerRegistered = getRuntimeContext().getState(new ValueStateDescriptor<>("timerRegistered", Boolean.class));
        }

        @Override
        public void processElement(Tuple2<Long, Long> value, Context ctx, Collector<String> out) throws Exception {
            Long current = maxStageCount.value();
            if (current == null || value.f1 > current) {
                maxStageCount.update(value.f1);
            }

            Boolean isFinished = finished.value();
            if (Boolean.TRUE.equals(isFinished)) {
                registerOnce(ctx);
            }
        }

        public void processFinished(Context ctx) throws Exception {
            finished.update(true);
            registerOnce(ctx);
        }

        private void registerOnce(Context ctx) throws Exception {
            Boolean already = timerRegistered.value();
            if (!Boolean.TRUE.equals(already)) {
                ctx.timerService().registerEventTimeTimer(maxEventTime);
                timerRegistered.update(true);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Boolean isFinished = finished.value();
            if (!Boolean.TRUE.equals(isFinished)) {
                return;
            }
            Long count = maxStageCount.value();
            long result = count == null ? 0L : count;
            out.collect("(" + ctx.getCurrentKey() + "," + result + ")");

            maxStageCount.clear();
            finished.clear();
            timerRegistered.clear();
        }
    }

    private static final class FinishedMarker extends KeyedProcessFunction<Long, JobEvent, JobEvent> {
        private final EmitAfterFinished downstream;

        private FinishedMarker(EmitAfterFinished downstream) {
            this.downstream = downstream;
        }

        @Override
        public void processElement(JobEvent value, Context ctx, Collector<JobEvent> out) throws Exception {
            downstream.processFinished((KeyedProcessFunction<Long, Tuple2<Long, Long>, String>.Context) (Object) ctx);
            out.collect(value);
        }
    }

    private static final class LocalTextFileSink extends RichSinkFunction<String> {
        private final String outputPath;
        private transient java.io.BufferedWriter writer;

        private LocalTextFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            if (outputPath == null) {
                return;
            }
            Path p = Paths.get(outputPath);
            Path parent = p.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            writer = Files.newBufferedWriter(
                    p,
                    StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING);
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            if (writer == null) {
                return;
            }
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forMonotonousTimestamps()
                .withTimestampAssigner((SerializableTimestampAssigner<TaskEvent>) (element, recordTimestamp) -> element.getTimestampMillis());

        WatermarkStrategy<JobEvent> jobWm = WatermarkStrategy
                .<JobEvent>forMonotonousTimestamps()
                .withTimestampAssigner((SerializableTimestampAssigner<JobEvent>) (element, recordTimestamp) -> element.getTimestampMillis());

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWm);

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWm);

        SingleOutputStreamOperator<Tuple2<Long, Long>> stageCounts = tasks
                .filter(e -> e.getEventType() == TaskEvent.EVENT_SUBMIT)
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new StageCountWindow());

        SingleOutputStreamOperator<Tuple2<Long, Long>> maxStageCounts = stageCounts
                .keyBy(t -> t.f0)
                .reduce(new MaxReduce());

        DataStream<JobEvent> finishedJobs = jobs
                .filter(JobEvent::isTerminal)
                .keyBy(JobEvent::getJobId)
                .reduce((a, b) -> a);

        // Emit results only for finished jobs, after all windows have closed.
        long endOfInputWatermark = Long.MAX_VALUE;

        ConnectedStreams<Tuple2<Long, Long>, JobEvent> connected = maxStageCounts.connect(finishedJobs);

        SingleOutputStreamOperator<String> results = connected
                .keyBy(t -> t.f0, JobEvent::getJobId)
                .process(new KeyedProcessFunction<Long, Object, String>() {
                    private transient ValueState<Long> maxStage;
                    private transient ValueState<Boolean> finished;
                    private transient ValueState<Boolean> timer;

                    @Override
                    public void open(Configuration parameters) {
                        maxStage = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStage", Long.class));
                        finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
                        timer = getRuntimeContext().getState(new ValueStateDescriptor<>("timer", Boolean.class));
                    }

                    @Override
                    public void processElement1(Object value, Context ctx, Collector<String> out) throws Exception {
                        @SuppressWarnings("unchecked")
                        Tuple2<Long, Long> v = (Tuple2<Long, Long>) value;
                        Long current = maxStage.value();
                        if (current == null || v.f1 > current) {
                            maxStage.update(v.f1);
                        }
                        if (Boolean.TRUE.equals(finished.value())) {
                            registerOnce(ctx);
                        }
                    }

                    @Override
                    public void processElement2(Object value, Context ctx, Collector<String> out) throws Exception {
                        finished.update(true);
                        registerOnce(ctx);
                    }

                    private void registerOnce(Context ctx) throws Exception {
                        if (!Boolean.TRUE.equals(timer.value())) {
                            ctx.timerService().registerEventTimeTimer(endOfInputWatermark);
                            timer.update(true);
                        }
                    }

                    @Override
                    public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
                        if (!Boolean.TRUE.equals(finished.value())) {
                            return;
                        }
                        Long count = maxStage.value();
                        long result = count == null ? 0L : count;
                        out.collect("(" + ctx.getCurrentKey() + "," + result + ")");
                        maxStage.clear();
                        finished.clear();
                        timer.clear();
                    }
                });

        results.addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalTextFileSink(outputPath)));

        env.execute("LongestSessionPerJob");
    }

}
